INSERT INTO growth_point_account (
    id, student_id, total_points, available_points, version_no
)
SELECT #{studentId}, #{studentId}, 0, 0, 0
WHERE NOT EXISTS (
    SELECT 1 FROM growth_point_account WHERE student_id = #{studentId}
)

mapper.update:
UPDATE growth_point_account
SET total_points = total_points + #{points},
    available_points = available_points + #{points},
    version_no = version_no + 1,
    updated_at = #{updatedAt}
WHERE id = #{id} AND version_no = #{expectedVersion}

UPDATE growth_point_account
SET total_points = total_points - #{totalDeduction},
    available_points = available_points - #{availableDeduction},
    version_no = version_no + 1,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND version_no = #{expectedVersion}
  AND total_points >= #{totalDeduction}
  AND available_points >= #{availableDeduction}

UPDATE growth_point_account
SET available_points = available_points - #{points},
    version_no = version_no + 1,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND version_no = #{expectedVersion}
  AND available_points >= #{points}

UPDATE growth_point_account
SET available_points = 0,
    version_no = version_no + 1,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND version_no = #{expectedVersion}
  AND available_points = #{points}
  AND #{points} > 0
